/*
 * intl.map - libintl.so version script
 *
 * glib 2.76 linked with meson/NDK r23 binds pthread_rwlock_* references to
 * the underscore names (_rwlock_trywrlock@LIBC) because NDK libc.so's
 * verdef defines them under those names. Huawei's libc only has the
 * standard names, so we must export the underscore names WITH a matching
 * LIBC version definition here (libintl.so is on glib's DT_NEEDED chain).
 */
LIBC {
  global:
    _rwlock_init;
    _rwlock_destroy;
    _rwlock_rdlock;
    _rwlock_wrlock;
    _rwlock_tryrdlock;
    _rwlock_trywrlock;
    _rwlock_unlock;
    _rwlock_timedrdlock;
    _rwlock_timedwrlock;
    free_sized;
    free_aligned_sized;
    close_range;
    g_libintl_gettext;
    g_libintl_dgettext;
    g_libintl_dcgettext;
    g_libintl_ngettext;
    g_libintl_dngettext;
    g_libintl_textdomain;
    g_libintl_bindtextdomain;
    g_libintl_bind_textdomain_codeset;
  local:
    *;
};